css:
.fe-stage, .dp-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.fe-stage canvas, .dp-stage canvas { touch-action: none; cursor: grab; }
.fe-stage canvas.holding, .dp-stage canvas.holding { cursor: grabbing; }
.fe-meter, .dp-meter { margin: 0; font-size: 19px; }
.fe-meter small, .dp-meter small { color: var(--ink-2); }
.fe-out, .dp-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 3.2em; }

